import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
import { acceptBlocksEvent, BlockHasher, BlockPullVerifier, blockCountFor, blockPlanFor, blockSizeFor, rootOf } from './fsBlocks';
import { FS_BLOCKS, FS_BLOCKS_RELEASE, filesExt, negotiate } from './extensions';

/**
 * `fs.blocks` — the block rule, held to `docs/fixtures/fs-blocks.json`. The fixture was generated by
 * an independent Python implementation, so a shared misunderstanding between this file and the
 * phone's `FsBlocks.kt` cannot pass both.
 */
const fixture = JSON.parse(readFileSync(join(__dirname, '..', '..', '..', 'docs', 'fixtures', 'fs-blocks.json'), 'utf8')) as {
  blockSize: { label: string; size: number; blockSize: number; blockCount: number }[];
  content: { length: number; blockSize: number; blocks: string[]; manifestRoot: string; prefixRoots: Record<string, string>; sha256: string };
  ext: { mac: Record<string, number>; phone: Record<string, number>; negotiated: number | null }[];
};

const content = (): Buffer => {
  const b = Buffer.alloc(fixture.content.length);
  for (let i = 0; i < b.length; i += 1) b[i] = i % 251;
  return b;
};

test('the block size and count agree with the fixture for every case, including both sides of 2000 blocks', () => {
  assert.ok(fixture.blockSize.length >= 8, 'control: the fixture has its cases');
  for (const c of fixture.blockSize) {
    assert.equal(blockSizeFor(c.size), c.blockSize, c.label);
    assert.equal(blockCountFor(c.size, c.blockSize), c.blockCount, c.label);
  }
});

test('block digests, the manifest root and the prefix roots match the fixture, whatever the chunking', () => {
  const bytes = content();
  for (const chunk of [1, 4096, 100_000, 131_072, 262_144, bytes.length]) {
    const h = new BlockHasher(fixture.content.blockSize);
    for (let at = 0; at < bytes.length; at += chunk) h.update(bytes.subarray(at, at + chunk));
    assert.deepEqual(h.finish(), fixture.content.blocks, `chunk ${chunk}`);
  }
  assert.equal(rootOf(fixture.content.blocks), fixture.content.manifestRoot);
  assert.equal(rootOf(fixture.content.blocks, 1), fixture.content.prefixRoots['1']);
  assert.equal(rootOf(fixture.content.blocks, 2), fixture.content.prefixRoots['2']);
});

test('finish is idempotent and an empty stream has no blocks', () => {
  const h = new BlockHasher(131_072);
  assert.deepEqual(h.finish(), []);
  h.update(Buffer.from([1]));
  assert.equal(h.finish().length, 1);
  assert.equal(h.finish().length, 1);
});

test('negotiation of fs.blocks follows the ext rules in the fixture', () => {
  for (const c of fixture.ext) assert.equal(negotiate(c.mac, c.phone, 'fs.blocks'), c.negotiated, JSON.stringify(c));
});

test('a blocks event is accepted only in order, bounded, and well formed', () => {
  const d = 'a'.repeat(64);
  assert.deepEqual(acceptBlocksEvent(0, 10, { first: 0, sha256: [d, d] }), { ok: true, digests: [d, d] });
  const refused = (why: string, r: ReturnType<typeof acceptBlocksEvent>) => assert.equal(r.ok, false, why);
  refused('a gap', acceptBlocksEvent(2, 10, { first: 3, sha256: [d] }));
  refused('a repeat', acceptBlocksEvent(2, 10, { first: 1, sha256: [d] }));
  refused('past the count', acceptBlocksEvent(9, 10, { first: 9, sha256: [d, d] }));
  refused('upper-case hex', acceptBlocksEvent(0, 10, { first: 0, sha256: ['A'.repeat(64)] }));
  refused('short digest', acceptBlocksEvent(0, 10, { first: 0, sha256: ['a'.repeat(63)] }));
  refused('empty', acceptBlocksEvent(0, 10, { first: 0, sha256: [] }));
  refused('not an integer', acceptBlocksEvent(0, 10, { first: '0', sha256: [d] }));
  refused('257 digests', acceptBlocksEvent(0, 1000, { first: 0, sha256: Array(257).fill(d) }));
  assert.equal(acceptBlocksEvent(0, 1000, { first: 0, sha256: Array(256).fill(d) }).ok, true, 'control: 256 is allowed');
});

// ---- BlockPullVerifier: the Mac's half, fed exactly what the phone would send ---------------------

/** Seeded bytes (an LCG), so every block hashes differently. */
function seeded(n: number, seed = 12345): Buffer {
  const b = Buffer.alloc(n);
  let x = seed >>> 0;
  for (let i = 0; i < n; i += 1) { x = (Math.imul(x, 1664525) + 1013904223) >>> 0; b[i] = x >>> 24; }
  return b;
}
const sha = (b: Uint8Array): string => createHash('sha256').update(b).digest('hex');
const BS = 4096;
const SRC = seeded(10 * BS + 123);
const COUNT = blockCountFor(SRC.length, BS);
const PHONE = Array.from({ length: COUNT }, (_, i) => sha(SRC.subarray(i * BS, Math.min(SRC.length, (i + 1) * BS))));
const DONE = { ok: true, bytes: SRC.length, sha256: sha(SRC), blockSize: BS, blockCount: COUNT, manifestRoot: rootOf(PHONE) };

/** Feeds bytes in chunks and the phone's digests in batches after their bytes, like the wire. */
function run(v: BlockPullVerifier, bytes: Buffer, from = 0, digests: string[] = PHONE, chunk = 1000): void {
  let sentUpTo = Math.floor(from / BS);
  for (let at = from; at < bytes.length; at += chunk) {
    v.onBytes(bytes.subarray(at, Math.min(bytes.length, at + chunk)));
    const complete = Math.floor(Math.min(bytes.length, at + chunk) / BS);
    if (complete >= sentUpTo + 3) { v.onBlocks({ first: sentUpTo, sha256: digests.slice(sentUpTo, complete) }); sentUpTo = complete; }
  }
  if (sentUpTo < digests.length) v.onBlocks({ first: sentUpTo, sha256: digests.slice(sentUpTo) });
}

test('verifier: a faithful transfer is verified, and every block counted', () => {
  assert.equal(new Set(PHONE).size, COUNT, 'control: every block of the source hashes differently');
  const v = new BlockPullVerifier(SRC.length, BS, COUNT);
  run(v, SRC);
  v.onDone(DONE);
  assert.deepEqual(v.conclude(sha(SRC), SRC.length), { kind: 'verified' });
  assert.equal(v.verified, COUNT);
});

test('verifier: one flipped byte is caught at its own block, before the transfer ends', () => {
  const bad = Buffer.from(SRC);
  bad[5 * BS + 17] ^= 0xff;
  const v = new BlockPullVerifier(SRC.length, BS, COUNT);
  run(v, bad);
  assert.equal(v.failure?.kind, 'corrupt');
  assert.equal((v.failure as { block?: number }).block, 5);
  assert.equal(v.verified, 5, 'the five blocks before it stay verified — what a resume may keep');
  v.onDone(DONE);
  assert.equal(v.conclude(sha(bad), bad.length).kind, 'corrupt');
});

test('verifier: a flip in the short final block is caught at the end', () => {
  const bad = Buffer.from(SRC);
  bad[SRC.length - 1] ^= 1;
  const v = new BlockPullVerifier(SRC.length, BS, COUNT);
  run(v, bad);
  assert.equal(v.failure, null, 'the last block cannot close until the end');
  v.onDone(DONE);
  assert.equal(v.conclude(sha(bad), bad.length).kind, 'corrupt');
});

test('verifier: missing digests, a wrong manifest, a wrong whole-file hash, or a wrong length are each corrupt', () => {
  const cases: Array<[string, (v: BlockPullVerifier) => void, Record<string, unknown>, string?, number?]> = [
    ['last digest never sent', (v) => run(v, SRC, 0, PHONE.slice(0, -1)), DONE],
    ['wrong manifest root', (v) => run(v, SRC), { ...DONE, manifestRoot: 'f'.repeat(64) }],
    ['wrong whole-file sha from the phone', (v) => run(v, SRC), { ...DONE, sha256: 'f'.repeat(64) }],
    ['wrong block count reported', (v) => run(v, SRC), { ...DONE, blockCount: COUNT + 1 }],
    ['phone reports another length', (v) => run(v, SRC), { ...DONE, bytes: SRC.length - 1 }],
    ['Mac wrote fewer bytes', (v) => run(v, SRC.subarray(0, SRC.length - 5)), DONE, sha(SRC.subarray(0, SRC.length - 5)), SRC.length - 5],
  ];
  for (const [label, feed, done, macSha, bytes] of cases) {
    const v = new BlockPullVerifier(SRC.length, BS, COUNT);
    feed(v);
    v.onDone(done);
    const got = v.conclude(macSha ?? sha(SRC), bytes ?? SRC.length);
    assert.equal(got.kind, 'corrupt', `${label}: ${JSON.stringify(got)}`);
  }
});

test('verifier: SOURCE_CHANGED and any other phone failure are not verified, and not called corrupt', () => {
  const v = new BlockPullVerifier(SRC.length, BS, COUNT);
  run(v, SRC.subarray(0, 3 * BS), 0, PHONE.slice(0, 3));
  v.onDone({ ok: false, code: 'SOURCE_CHANGED', why: 'source-changed', message: 'clip.mov changed on the phone' });
  assert.deepEqual(v.conclude(sha(SRC.subarray(0, 3 * BS)), 3 * BS), { kind: 'source-changed', why: 'source-changed', message: 'clip.mov changed on the phone' });
  const w = new BlockPullVerifier(SRC.length, BS, COUNT);
  w.onDone({ ok: false, code: 'TRANSFER_FAILED', message: 'stopped' });
  assert.equal(w.conclude('', 0).kind, 'failed');
});

test('verifier: out-of-order, repeated or oversized digest events fail the transfer', () => {
  for (const ev of [{ first: 1, sha256: [PHONE[1]] }, { first: 0, sha256: ['X'] }, { first: 0, sha256: PHONE.concat(PHONE) }]) {
    const v = new BlockPullVerifier(SRC.length, BS, COUNT);
    v.onBlocks(ev);
    assert.equal(v.failure?.kind, 'failed', JSON.stringify(ev).slice(0, 60));
  }
});

test('verifier: no done within the wait is a timeout, not a verdict', async () => {
  const v = new BlockPullVerifier(SRC.length, BS, COUNT);
  run(v, SRC);
  assert.equal(await v.settled(20), 'timeout');
  assert.equal(v.conclude(sha(SRC), SRC.length).kind, 'failed');
  const w = new BlockPullVerifier(SRC.length, BS, COUNT);
  setTimeout(() => w.onDone(DONE), 5);
  assert.equal(await w.settled(1000), 'settled');
});

test('verifier: a resume starts from the record and verifies only the new blocks', () => {
  const v = new BlockPullVerifier(SRC.length, BS, COUNT, PHONE.slice(0, 4));
  assert.equal(v.verified, 4);
  run(v, SRC, 4 * BS);
  v.onDone(DONE);
  assert.deepEqual(v.conclude(sha(SRC), SRC.length), { kind: 'verified' });
  assert.deepEqual(v.verifiedDigests(), PHONE);
});

// ---- which pulls take the block path on the Mac, and what the Mac advertises -----------------------

test('blockPlanFor: an older phone and a non-negotiated session keep the old path; a bad plan is refused', () => {
  const on = { [FS_BLOCKS]: 1 };
  const GiB = 1024 ** 3;
  assert.deepEqual(blockPlanFor({}, { size: GiB, blockSize: null, blockCount: null }), { kind: 'none' }, 'older phone, older Mac');
  assert.equal(blockPlanFor({}, { size: GiB, blockSize: 1 << 20, blockCount: 1024 }).kind, 'ignored', 'block fields without negotiation (S1)');
  assert.deepEqual(blockPlanFor(on, { size: GiB, blockSize: null, blockCount: null }), { kind: 'none' }, 'negotiated, but the phone used the old path (<= 64 MiB)');
  assert.deepEqual(blockPlanFor(on, { size: GiB, blockSize: 1 << 20, blockCount: 1024 }), { kind: 'blocks', blockSize: 1 << 20, blockCount: 1024 });
  assert.equal(blockPlanFor(on, { size: GiB, blockSize: 1 << 19, blockCount: 2048 }).kind, 'refused', 'a block size off the rule');
  assert.equal(blockPlanFor(on, { size: GiB, blockSize: 1 << 20, blockCount: 1025 }).kind, 'refused', 'a count off the rule');
  assert.equal(blockPlanFor(on, { size: 64 * 1024 * 1024, blockSize: 1 << 17, blockCount: 512 }).kind, 'refused', 'blocks on a 64 MiB file');
});

test('the Mac advertises fs.blocks when unpackaged, or packaged only once released — and the switch is off', () => {
  assert.deepEqual(filesExt(false), { [FS_BLOCKS]: 1 });
  assert.deepEqual(filesExt(true), {});
  assert.deepEqual(filesExt(true, true), { [FS_BLOCKS]: 1 });
  assert.equal(FS_BLOCKS_RELEASE, false);
});
